// Real saved results -> background watcher -> HTTP bridge -> current feedback/report.
// Requires the isolated fixture generated by scripts/verify-quality-workflows.py.
const assert=require('assert'),fs=require('fs'),path=require('path'),{spawn}=require('child_process');
const root=path.resolve(__dirname,'..'),fixture=process.env.QUALITY_FIXTURE_ROOT;
if(!fixture)throw new Error('Set QUALITY_FIXTURE_ROOT to the isolated verification fixture.');
const port=Number(process.env.QUALITY_UI_PORT||0);
let base;
const child=spawn(process.execPath,[path.join(__dirname,'quality-ui-server.js')],{cwd:root,windowsHide:true,env:{...process.env,QUALITY_UI_PORT:String(port)},stdio:['ignore','pipe','pipe']});
let logs='';child.stderr.on('data',d=>logs+=d);
const ready=new Promise((resolve,reject)=>{
  let buffer='';
  const timer=setTimeout(()=>reject(new Error('Isolated server did not start: '+logs)),10000);
  child.once('error',error=>{clearTimeout(timer);reject(error);});
  child.once('exit',()=>{clearTimeout(timer);reject(new Error('Isolated server stopped: '+logs));});
  child.stdout.on('data',data=>{
    logs+=data;buffer+=data;
    while(buffer.includes('\n')){
      const end=buffer.indexOf('\n'),line=buffer.slice(0,end);buffer=buffer.slice(end+1);
      let value;try{value=JSON.parse(line);}catch{continue;}
      if(value.ready&&path.resolve(value.fixture)===path.resolve(fixture)){
        base=`http://127.0.0.1:${value.port}`;clearTimeout(timer);resolve();
      }
    }
  });
});
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function post(action,body={}){
  const response=await fetch(`${base}/api/quality-learning/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});
  const result=await response.json();assert.equal(result.ok,true,JSON.stringify(result));return result;
}
(async()=>{
  try{
    await ready;
    let state;
    for(let i=0;i<60;i++){
      if(child.exitCode!==null)throw new Error(logs);
      try{state=await post('state');if(state.results.length===4)break;}catch(error){if(i===59)throw error;}
      await pause(500);
    }
    assert.equal(state.results.length,4,JSON.stringify(state));
    assert.deepEqual(new Set(state.results.map(r=>r.task)),new Set(['text-to-image','inpaint','tryon','outpaint']));
    let report=(await post('report')).report;
    assert.equal(report.total.recorded,4);assert.equal(report.total.assessmentTime.samples,4);
    assert.equal(report.total.rated,0);assert.equal(report.total.compared,0);
    const evidence=[];
    for(const result of state.results){
      await post('feedback',{resultId:result.id,target:'original',rating:'good'});
      report=(await post('report')).report;
      assert.equal(report.tasks.find(r=>r.task===result.task).good,1);
      assert.equal(report.total.compared,0);
      await post('feedback',{resultId:result.id,target:'original',rating:'needs-work',defects:['blur']});
      report=(await post('report')).report;
      assert.equal(report.tasks.find(r=>r.task===result.task).needsWork,1);
      if(result.improved){
        await post('feedback',{resultId:result.id,target:'improved',preference:'improved'});
        assert.equal((await post('report')).report.total.preferImprovedRate,1);
        await post('feedback',{resultId:result.id,target:'original',preference:'tie'});
        assert.equal((await post('report')).report.total.preferImprovedRate,0);
      }
      await post('feedback',{resultId:result.id,target:'original',rating:'clear'});
      report=(await post('report')).report;
      assert.equal(report.total.rated,0);assert.equal(report.total.compared,0);
      evidence.push({task:result.task,status:result.status,ratingEditAndClear:true,pairComparisonVerified:Boolean(result.improved)});
    }
    fs.writeFileSync(path.join(fixture,'..','feedback-verification.json'),JSON.stringify({ok:true,isolated:true,cases:evidence,report},null,2));
    console.log('OK: four real output types, automatic watcher, HTTP feedback edits/clear, report denominators and measured timing.');
  }finally{child.kill();}
})().catch(error=>{console.error(error);process.exitCode=1;});
